import java.io.*;
import java.math.*;
import java.security.*;
import java.sql.*;
import java.text.*;
import java.util.*;

public class BankBatchJob {

    // Must be a single literal string and used at runtime.
    private static final String JDBC_URL = "jdbc:h2:/app/output/bankdb;MODE=DB2";

    private static final File DATA_DIR = new File("/app/data");
    private static final File OUT_DIR = new File("/app/output");

    private static final RoundingMode RM = RoundingMode.HALF_EVEN;

    private static final TimeZone UTC = TimeZone.getTimeZone("UTC");

    private static final SimpleDateFormat YYYY_MM_DD = new SimpleDateFormat("yyyy-MM-dd");
    static {
        YYYY_MM_DD.setLenient(false);
        YYYY_MM_DD.setTimeZone(UTC);
    }

    private static class Account {
        String accountId;
        Date openedAt;
        BigDecimal startBalance;
        BigDecimal baseApr;
        BigDecimal promoApr;
        int promoDays;
        BigDecimal tierThreshold;
        BigDecimal tierApr;
        String currency;
        String feePlan;

        // computed
        BigDecimal eodBalance;
        BigDecimal apr;
        BigDecimal dailyInterestRaw;
    }

    private static class FeeRule {
        String feePlan;
        String appliesTo; // DEBIT/CREDIT/ALL
        BigDecimal flatFee;
        BigDecimal pctFee;
        BigDecimal minFee;
        BigDecimal maxFee;
    }

    private static class Txn {
        int rowNum; // 1-based data row
        String txId;
        String accountId;
        Date effectiveDate;
        BigDecimal amount;
        String currency;
        String status;
        String reversalOf;

        boolean valid;
        String reason; // if skipped

        // derived for processing
        BigDecimal amountAcct; // converted to account currency, 2dp
        BigDecimal fee; // 2dp
        BigDecimal adjusted; // 2dp
    }

    private static class FxRate {
        Date rateDate;
        String from;
        String to;
        BigDecimal rate; // as provided
    }

    public static void main(String[] args) throws Exception {
        OUT_DIR.mkdirs();

        // Clean known outputs for deterministic reruns.
        deleteIfExists(new File(OUT_DIR, "interest.csv"));
        deleteIfExists(new File(OUT_DIR, "exceptions.csv"));
        deleteIfExists(new File(OUT_DIR, "stats.json"));
        deleteIfExists(new File(OUT_DIR, "bankdb.h2.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.trace.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.lock.db"));

        Date bizDate = readBizDate(new File(DATA_DIR, "biz_date.txt"));

        Map<String, Account> accounts = readAccounts(new File(DATA_DIR, "accounts.csv"));
        Map<String, FeeRule> feeRules = readFeeRules(new File(DATA_DIR, "fee_rules.csv"));
        List<String> pivots = readPivots(new File(DATA_DIR, "fx_pivots.csv"));
        List<FxRate> fxRates = readFxRates(new File(DATA_DIR, "fx_rates.csv"));
        List<Txn> txns = readTxns(new File(DATA_DIR, "transactions.csv"));

        // Precompute tx_id set.
        Set<String> txIdSet = new HashSet<String>();
        for (Txn t : txns) txIdSet.add(t.txId);

        // Determine REVERSED tx_ids: both rows if any row has reversal_of pointing to a tx_id in the file.
        Set<String> reversedTxIds = new HashSet<String>();
        for (Txn t : txns) {
            if (t.reversalOf != null && t.reversalOf.length() > 0) {
                if (txIdSet.contains(t.reversalOf)) {
                    reversedTxIds.add(t.txId);
                    reversedTxIds.add(t.reversalOf);
                }
            }
        }

        // Track duplicates: any tx_id after first appearance (even if first row invalid)
        Set<String> seen = new HashSet<String>();

        int validTxs = 0;
        int skippedTxs = 0;

        // Process each txn in file order applying reason precedence.
        for (Txn t : txns) {
            String reason = null;

            boolean isDuplicate = seen.contains(t.txId);
            seen.add(t.txId);

            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !txIdSet.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else if (!accounts.containsKey(t.accountId)) {
                reason = "ACCOUNT_MISSING";
            } else {
                Account acct = accounts.get(t.accountId);
                // FX_MISSING check is before date/status/duplicate.
                BigDecimal fx = null;
                if (t.currency.equals(acct.currency)) {
                    fx = BigDecimal.ONE.setScale(10, RM);
                } else {
                    fx = resolveFxRate(fxRates, pivots, t.currency, acct.currency, t.effectiveDate);
                    if (fx == null) {
                        reason = "FX_MISSING";
                    }
                }

                if (reason == null) {
                    if (t.effectiveDate.after(bizDate)) {
                        reason = "AFTER_BIZ_DATE";
                    } else if (!"POSTED".equals(t.status)) {
                        reason = t.status;
                    } else if (isDuplicate) {
                        reason = "DUPLICATE";
                    } else {
                        // Valid. Apply conversion + fees.
                        t.amountAcct = t.amount.multiply(fx).setScale(2, RM);
                        FeeRule fr = feeRules.get(acct.feePlan);
                        t.fee = computeFee(fr, t.amountAcct);
                        t.adjusted = t.amountAcct.subtract(t.fee).setScale(2, RM);
                        t.valid = true;
                        validTxs++;
                    }
                }
            }

            if (reason != null) {
                t.valid = false;
                t.reason = reason;
                skippedTxs++;
            }
        }

        // Aggregate balances.
        for (Account a : accounts.values()) {
            BigDecimal sum = BigDecimal.ZERO.setScale(2, RM);
            for (Txn t : txns) {
                if (t.valid && a.accountId.equals(t.accountId)) {
                    sum = sum.add(t.adjusted).setScale(2, RM);
                }
            }
            a.eodBalance = a.startBalance.add(sum).setScale(2, RM);

            boolean promoActive = false;
            if (a.promoDays > 0) {
                int days = daysBetween(a.openedAt, bizDate);
                promoActive = days < a.promoDays;
            }

            BigDecimal apr = a.baseApr;
            if (a.eodBalance.compareTo(a.tierThreshold) >= 0) {
                apr = apr.add(a.tierApr);
            }
            if (promoActive) {
                apr = apr.add(a.promoApr);
            }
            a.apr = apr;

            BigDecimal principal = a.eodBalance.max(BigDecimal.ZERO);
            // daily_interest_raw = principal * apr/365 (HALF_EVEN 10dp)
            BigDecimal dailyRate = a.apr.divide(new BigDecimal("365"), 10, RM);
            a.dailyInterestRaw = principal.multiply(dailyRate).setScale(10, RM);
        }

        // Write interest.csv
        File interestFile = new File(OUT_DIR, "interest.csv");
        writeInterestCsv(interestFile, bizDate, accounts);

        // Compute md5 of interest.csv bytes
        String reportMd5 = md5HexOfFile(interestFile);

        // Write exceptions.csv
        File exceptionsFile = new File(OUT_DIR, "exceptions.csv");
        writeExceptionsCsv(exceptionsFile, txns);

        // total_interest = sum(daily_interest_raw keep 10dp) rounded to 2dp
        BigDecimal totalInterestRaw = BigDecimal.ZERO.setScale(10, RM);
        for (Account a : accounts.values()) {
            totalInterestRaw = totalInterestRaw.add(a.dailyInterestRaw).setScale(10, RM);
        }
        BigDecimal totalInterest = totalInterestRaw.setScale(2, RM);

        // stats.json single line, no newline
        File statsFile = new File(OUT_DIR, "stats.json");
        writeStatsJsonNoNewline(statsFile, bizDate, accounts.size(), validTxs, skippedTxs, totalInterest, reportMd5);

        // Create H2 DB
        writeH2Db(bizDate, accounts, txns, validTxs, skippedTxs, reportMd5);
    }

    private static void deleteIfExists(File f) {
        if (f.exists()) {
            // best effort
            f.delete();
        }
    }

    private static Date readBizDate(File f) throws Exception {
        String s = readAllTrimmed(f);
        return parseDate(s);
    }

    private static String readAllTrimmed(File f) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
        try {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) sb.append(line);
            return sb.toString().trim();
        } finally {
            br.close();
        }
    }

    private static Map<String, Account> readAccounts(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        Map<String, Account> m = new HashMap<String, Account>();
        // header expected
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            Account a = new Account();
            a.accountId = r[0];
            a.openedAt = parseDate(r[1]);
            a.startBalance = new BigDecimal(r[2]).setScale(2, RM);
            a.baseApr = new BigDecimal(r[3]);
            a.promoApr = new BigDecimal(r[4]);
            a.promoDays = Integer.parseInt(r[5]);
            a.tierThreshold = new BigDecimal(r[6]).setScale(2, RM);
            a.tierApr = new BigDecimal(r[7]);
            a.currency = r[8];
            a.feePlan = r[9];
            m.put(a.accountId, a);
        }
        return m;
    }

    private static Map<String, FeeRule> readFeeRules(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        Map<String, FeeRule> m = new HashMap<String, FeeRule>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            FeeRule fr = new FeeRule();
            fr.feePlan = r[0];
            fr.appliesTo = r[1];
            fr.flatFee = new BigDecimal(r[2]);
            fr.pctFee = new BigDecimal(r[3]);
            fr.minFee = new BigDecimal(r[4]);
            fr.maxFee = new BigDecimal(r[5]);
            m.put(fr.feePlan, fr);
        }
        return m;
    }

    private static List<String> readPivots(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        List<String> pivots = new ArrayList<String>();
        for (int i = 1; i < rows.size(); i++) {
            pivots.add(rows.get(i)[0]);
        }
        return pivots;
    }

    private static List<FxRate> readFxRates(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        List<FxRate> list = new ArrayList<FxRate>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            FxRate fr = new FxRate();
            fr.rateDate = parseDate(r[0]);
            fr.from = r[1];
            fr.to = r[2];
            fr.rate = new BigDecimal(r[3]);
            list.add(fr);
        }
        return list;
    }

    private static List<Txn> readTxns(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        List<Txn> list = new ArrayList<Txn>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            Txn t = new Txn();
            t.rowNum = i; // 1-based data row
            t.txId = r[0];
            t.accountId = r[1];
            t.effectiveDate = parseDate(r[2]);
            t.amount = new BigDecimal(r[3]).setScale(2, RM);
            t.currency = r[4];
            t.status = r[5];
            t.reversalOf = r.length > 6 ? r[6] : "";
            if (t.reversalOf == null) t.reversalOf = "";
            list.add(t);
        }
        return list;
    }

    private static List<String[]> readCsv(File f) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
        try {
            List<String[]> rows = new ArrayList<String[]>();
            String line;
            while ((line = br.readLine()) != null) {
                // simple CSV (no quoted fields expected)
                String[] parts = line.split(",", -1);
                for (int i = 0; i < parts.length; i++) parts[i] = parts[i].trim();
                rows.add(parts);
            }
            return rows;
        } finally {
            br.close();
        }
    }

    private static Date parseDate(String s) throws ParseException {
        synchronized (YYYY_MM_DD) {
            return YYYY_MM_DD.parse(s);
        }
    }

    private static String formatDate(Date d) {
        synchronized (YYYY_MM_DD) {
            return YYYY_MM_DD.format(d);
        }
    }

    private static int daysBetween(Date start, Date end) {
        long ms = end.getTime() - start.getTime();
        return (int)(ms / 86400000L);
    }

    private static BigDecimal computeFee(FeeRule fr, BigDecimal amountAcct) {
        if (fr == null) {
            return BigDecimal.ZERO.setScale(2, RM);
        }
        int sign = amountAcct.signum();
        boolean debit = sign < 0;
        boolean credit = sign > 0;

        boolean applies = false;
        if ("ALL".equals(fr.appliesTo)) applies = true;
        else if ("DEBIT".equals(fr.appliesTo) && debit) applies = true;
        else if ("CREDIT".equals(fr.appliesTo) && credit) applies = true;

        if (!applies) {
            return BigDecimal.ZERO.setScale(2, RM);
        }

        BigDecimal base = fr.flatFee.add(fr.pctFee.multiply(amountAcct.abs()));
        BigDecimal fee = base.setScale(2, RM);
        if (fee.compareTo(fr.minFee) < 0) fee = fr.minFee;
        if (fee.compareTo(fr.maxFee) > 0) fee = fr.maxFee;
        fee = fee.setScale(2, RM);
        return fee;
    }

    private static BigDecimal resolveFxRate(List<FxRate> allRates, List<String> pivots, String from, String to, Date effectiveDate) {
        BigDecimal direct = resolveFxLeg(allRates, from, to, effectiveDate);
        if (direct != null) return direct;

        // Try pivots in order.
        for (int i = 0; i < pivots.size(); i++) {
            String p = pivots.get(i);
            if (p.equals(from) || p.equals(to)) continue;
            BigDecimal leg1 = resolveFxLeg(allRates, from, p, effectiveDate);
            if (leg1 == null) continue;
            BigDecimal leg2 = resolveFxLeg(allRates, p, to, effectiveDate);
            if (leg2 == null) continue;
            return leg1.multiply(leg2).setScale(10, RM);
        }
        return null;
    }

    private static BigDecimal resolveFxLeg(List<FxRate> allRates, String from, String to, Date effectiveDate) {
        FxRate bestDirect = latestRate(allRates, from, to, effectiveDate);
        FxRate bestReverse = latestRate(allRates, to, from, effectiveDate);

        if (bestDirect == null && bestReverse == null) return null;
        if (bestDirect != null && bestReverse == null) {
            return bestDirect.rate.setScale(10, RM);
        }
        if (bestDirect == null && bestReverse != null) {
            return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);
        }

        // Both exist: choose newer one; if tied, use direct.
        int cmp = bestDirect.rateDate.compareTo(bestReverse.rateDate);
        if (cmp > 0) {
            return bestDirect.rate.setScale(10, RM);
        } else if (cmp < 0) {
            return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);
        } else {
            return bestDirect.rate.setScale(10, RM);
        }
    }

    private static FxRate latestRate(List<FxRate> allRates, String from, String to, Date effectiveDate) {
        FxRate best = null;
        for (int i = 0; i < allRates.size(); i++) {
            FxRate r = allRates.get(i);
            if (!r.from.equals(from)) continue;
            if (!r.to.equals(to)) continue;
            if (r.rateDate.after(effectiveDate)) continue;
            if (best == null || r.rateDate.after(best.rateDate)) {
                best = r;
            }
        }
        return best;
    }

    private static void writeInterestCsv(File f, Date bizDate, Map<String, Account> accounts) throws Exception {
        List<String> ids = new ArrayList<String>(accounts.keySet());
        Collections.sort(ids);
        OutputStream os = new FileOutputStream(f);
        Writer w = new OutputStreamWriter(os, "UTF-8");
        try {
            w.write("account_id,biz_date,eod_balance,apr,daily_interest\n");
            for (int i = 0; i < ids.size(); i++) {
                Account a = accounts.get(ids.get(i));
                BigDecimal apr6 = a.apr.setScale(6, RM);
                BigDecimal di2 = a.dailyInterestRaw.setScale(2, RM);
                w.write(a.accountId);
                w.write(',');
                w.write(formatDate(bizDate));
                w.write(',');
                w.write(a.eodBalance.setScale(2, RM).toPlainString());
                w.write(',');
                w.write(apr6.toPlainString());
                w.write(',');
                w.write(di2.toPlainString());
                w.write("\n");
            }
        } finally {
            w.close();
        }
    }

    private static void writeExceptionsCsv(File f, List<Txn> txns) throws Exception {
        OutputStream os = new FileOutputStream(f);
        Writer w = new OutputStreamWriter(os, "UTF-8");
        try {
            w.write("row_num,tx_id,reason\n");
            for (int i = 0; i < txns.size(); i++) {
                Txn t = txns.get(i);
                if (t.valid) continue;
                w.write(Integer.toString(t.rowNum));
                w.write(',');
                w.write(t.txId);
                w.write(',');
                w.write(t.reason);
                w.write("\n");
            }
        } finally {
            w.close();
        }
    }

    private static String md5HexOfFile(File f) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        InputStream is = new FileInputStream(f);
        try {
            byte[] buf = new byte[8192];
            int n;
            while ((n = is.read(buf)) > 0) {
                md.update(buf, 0, n);
            }
        } finally {
            is.close();
        }
        byte[] dig = md.digest();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dig.length; i++) {
            int b = dig[i] & 0xFF;
            String hx = Integer.toHexString(b);
            if (hx.length() == 1) sb.append('0');
            sb.append(hx);
        }
        return sb.toString();
    }

    private static void writeStatsJsonNoNewline(File f, Date bizDate, int accounts, int validTxs, int skippedTxs,
                                               BigDecimal totalInterest, String reportMd5) throws Exception {
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        sb.append("\"business_date\":\"").append(formatDate(bizDate)).append("\"");
        sb.append(",\"accounts\":").append(accounts);
        sb.append(",\"valid_txs\":").append(validTxs);
        sb.append(",\"skipped_txs\":").append(skippedTxs);
        sb.append(",\"total_interest\":\"").append(totalInterest.setScale(2, RM).toPlainString()).append("\"");
        sb.append(",\"report_md5\":\"").append(reportMd5).append("\"");
        sb.append('}');

        OutputStream os = new FileOutputStream(f);
        try {
            os.write(sb.toString().getBytes("UTF-8"));
        } finally {
            os.close();
        }
    }

    private static void writeH2Db(Date bizDate, Map<String, Account> accounts, List<Txn> txns,
                                  int validTxs, int skippedTxs, String reportMd5) throws Exception {

        Class.forName("org.h2.Driver");
        Connection conn = DriverManager.getConnection(JDBC_URL, "sa", "");
        try {
            Statement st = conn.createStatement();
            try {
                safeExec(st, "DROP TABLE RUN_AUDIT");
                safeExec(st, "DROP TABLE TXNS");
                safeExec(st, "DROP TABLE ACCOUNTS");

                st.execute("CREATE TABLE ACCOUNTS (" +
                        "ACCOUNT_ID VARCHAR(20) PRIMARY KEY," +
                        "OPENED_AT VARCHAR(10)," +
                        "START_BALANCE DECIMAL(18,2)," +
                        "BASE_APR DECIMAL(18,8)," +
                        "PROMO_APR DECIMAL(18,8)," +
                        "PROMO_DAYS INTEGER," +
                        "TIER_THRESHOLD DECIMAL(18,2)," +
                        "TIER_APR DECIMAL(18,8)," +
                        "CURRENCY VARCHAR(3)," +
                        "FEE_PLAN VARCHAR(20)" +
                        ")");

                st.execute("CREATE TABLE TXNS (" +
                        "ROW_NUM INTEGER PRIMARY KEY," +
                        "TX_ID VARCHAR(40)," +
                        "ACCOUNT_ID VARCHAR(20)," +
                        "EFFECTIVE_DATE VARCHAR(10)," +
                        "AMOUNT DECIMAL(18,2)," +
                        "CURRENCY VARCHAR(3)," +
                        "STATUS VARCHAR(20)," +
                        "REVERSAL_OF VARCHAR(40)" +
                        ")");

                st.execute("CREATE TABLE RUN_AUDIT (" +
                        "JDBC_URL VARCHAR(200)," +
                        "BIZ_DATE VARCHAR(10)," +
                        "ACCOUNTS INTEGER," +
                        "VALID_TXS INTEGER," +
                        "SKIPPED_TXS INTEGER," +
                        "REPORT_MD5 VARCHAR(40)" +
                        ")");
            } finally {
                st.close();
            }

            PreparedStatement pa = conn.prepareStatement(
                    "INSERT INTO ACCOUNTS(ACCOUNT_ID,OPENED_AT,START_BALANCE,BASE_APR,PROMO_APR,PROMO_DAYS,TIER_THRESHOLD,TIER_APR,CURRENCY,FEE_PLAN) VALUES (?,?,?,?,?,?,?,?,?,?)");
            try {
                List<String> ids = new ArrayList<String>(accounts.keySet());
                Collections.sort(ids);
                for (int i = 0; i < ids.size(); i++) {
                    Account a = accounts.get(ids.get(i));
                    pa.setString(1, a.accountId);
                    pa.setString(2, formatDate(a.openedAt));
                    pa.setBigDecimal(3, a.startBalance.setScale(2, RM));
                    pa.setBigDecimal(4, a.baseApr);
                    pa.setBigDecimal(5, a.promoApr);
                    pa.setInt(6, a.promoDays);
                    pa.setBigDecimal(7, a.tierThreshold.setScale(2, RM));
                    pa.setBigDecimal(8, a.tierApr);
                    pa.setString(9, a.currency);
                    pa.setString(10, a.feePlan);
                    pa.executeUpdate();
                }
            } finally {
                pa.close();
            }

            PreparedStatement pt = conn.prepareStatement(
                    "INSERT INTO TXNS(ROW_NUM,TX_ID,ACCOUNT_ID,EFFECTIVE_DATE,AMOUNT,CURRENCY,STATUS,REVERSAL_OF) VALUES (?,?,?,?,?,?,?,?)");
            try {
                for (int i = 0; i < txns.size(); i++) {
                    Txn t = txns.get(i);
                    pt.setInt(1, t.rowNum);
                    pt.setString(2, t.txId);
                    pt.setString(3, t.accountId);
                    pt.setString(4, formatDate(t.effectiveDate));
                    pt.setBigDecimal(5, t.amount.setScale(2, RM));
                    pt.setString(6, t.currency);
                    pt.setString(7, t.status);
                    pt.setString(8, (t.reversalOf == null ? "" : t.reversalOf));
                    pt.executeUpdate();
                }
            } finally {
                pt.close();
            }

            PreparedStatement pr = conn.prepareStatement(
                    "INSERT INTO RUN_AUDIT(JDBC_URL,BIZ_DATE,ACCOUNTS,VALID_TXS,SKIPPED_TXS,REPORT_MD5) VALUES (?,?,?,?,?,?)");
            try {
                pr.setString(1, JDBC_URL);
                pr.setString(2, formatDate(bizDate));
                pr.setInt(3, accounts.size());
                pr.setInt(4, validTxs);
                pr.setInt(5, skippedTxs);
                pr.setString(6, reportMd5);
                pr.executeUpdate();
            } finally {
                pr.close();
            }

            conn.commit();
        } finally {
            try { conn.close(); } catch (Exception e) { /* ignore */ }
        }
    }

    private static void safeExec(Statement st, String sql) {
        try {
            st.execute(sql);
        } catch (SQLException e) {
            // ignore
        }
    }
}
