public class BankBatchJob {

    // Must be a single literal string and used at runtime.
    private static final String JDBC_URL = "jdbc:h2:/app/output/bankdb;MODE=DB2";

    private static final File DATA_DIR = new File("/app/data");
    private static final File OUT_DIR = new File("/app/output");

    private static final RoundingMode RM = RoundingMode.HALF_EVEN;
    private static final TimeZone UTC = TimeZone.getTimeZone("UTC");

    private static final SimpleDateFormat YYYY_MM_DD = new SimpleDateFormat("yyyy-MM-dd");
    static {
        YYYY_MM_DD.setLenient(false);
        YYYY_MM_DD.setTimeZone(UTC);
    }

    private static class Account {
        String accountId;
        Date openedAt;
        BigDecimal startBalance;
        BigDecimal baseApr;
        BigDecimal promoApr;
        int promoDays;
        BigDecimal tierThreshold;
        BigDecimal tierApr;
        String currency;
        String feePlan;

        BigDecimal eodBalance;
        BigDecimal apr;
        BigDecimal dailyInterestRaw;
    }

    private static class FeeRule {
        String feePlan;
        String appliesTo; // DEBIT/CREDIT/ALL
        BigDecimal flatFee;
        BigDecimal pctFee;
        BigDecimal minFee;
        BigDecimal maxFee;
    }

    private static class Txn {
        int rowNum; // 1-based data row
        String txId;
        String accountId;
        Date effectiveDate;
        BigDecimal amount;
        String currency;
        String status;
        String reversalOf;

        boolean valid;
        String reason;

        BigDecimal amountAcct; // 2dp
        BigDecimal fee;       // 2dp
        BigDecimal adjusted;  // 2dp
    }

    private static class FxRate {
        Date rateDate;
        String from;
        String to;
        BigDecimal rate;
    }

    public static void main(String[] args) throws Exception {
        OUT_DIR.mkdirs();

        // Deterministic reruns: remove old outputs.
        deleteIfExists(new File(OUT_DIR, "interest.csv"));
        deleteIfExists(new File(OUT_DIR, "exceptions.csv"));
        deleteIfExists(new File(OUT_DIR, "stats.json"));
        deleteIfExists(new File(OUT_DIR, "bankdb.h2.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.trace.db"));
        deleteIfExists(new File(OUT_DIR, "bankdb.lock.db"));

        Date bizDate = readBizDate(new File(DATA_DIR, "biz_date.txt"));

        Map<String, Account> accounts = readAccounts(new File(DATA_DIR, "accounts.csv"));
        Map<String, FeeRule> feeRules = readFeeRules(new File(DATA_DIR, "fee_rules.csv"));
        List<String> pivots = readPivots(new File(DATA_DIR, "fx_pivots.csv"));
        List<FxRate> fxRates = readFxRates(new File(DATA_DIR, "fx_rates.csv"));
        List<Txn> txns = readTxns(new File(DATA_DIR, "transactions.csv"));

        Set<String> txIdSet = new HashSet<String>();
        for (Txn t : txns) txIdSet.add(t.txId);

        // REVERSED: both rows if reversal_of points to any tx_id in file (even if referenced row appears later)
        Set<String> reversedTxIds = new HashSet<String>();
        for (Txn t : txns) {
            if (t.reversalOf != null && t.reversalOf.length() > 0) {
                if (txIdSet.contains(t.reversalOf)) {
                    reversedTxIds.add(t.txId);
                    reversedTxIds.add(t.reversalOf);
                }
            }
        }

        Set<String> seen = new HashSet<String>();

        int validTxs = 0;
        int skippedTxs = 0;

        for (Txn t : txns) {
            boolean isDuplicate = seen.contains(t.txId);
            seen.add(t.txId);

            String reason = null;

            // Reasons in required precedence.
            if (reversedTxIds.contains(t.txId)) {
                reason = "REVERSED";
            } else if (t.reversalOf != null && t.reversalOf.length() > 0 && !txIdSet.contains(t.reversalOf)) {
                reason = "REVERSAL_MISSING";
            } else {
                Account acct = accounts.get(t.accountId);
                if (acct == null) {
                    // Not specified in the provided reason list, but needed to account for missing accounts.
                    reason = "ACCOUNT_MISSING";
                } else {
                    BigDecimal fx;
                    if (t.currency.equals(acct.currency)) {
                        fx = BigDecimal.ONE.setScale(10, RM);
                    } else {
                        fx = resolveFxRate(fxRates, pivots, t.currency, acct.currency, t.effectiveDate);
                        if (fx == null) {
                            reason = "FX_MISSING";
                        }
                    }

                    if (reason == null) {
                        if (t.effectiveDate.after(bizDate)) {
                            reason = "AFTER_BIZ_DATE";
                        } else if (!"POSTED".equals(t.status)) {
                            reason = t.status;
                        } else if (isDuplicate) {
                            reason = "DUPLICATE";
                        } else {
                            t.amountAcct = t.amount.multiply(fx).setScale(2, RM);
                            FeeRule fr = feeRules.get(acct.feePlan);
                            t.fee = computeFee(fr, t.amountAcct);
                            t.adjusted = t.amountAcct.subtract(t.fee).setScale(2, RM);
                            t.valid = true;
                            validTxs++;
                        }
                    }
                }
            }

            if (reason != null) {
                t.valid = false;
                t.reason = reason;
                skippedTxs++;
            }
        }

        // Compute EOD balances / APR / interest.
        for (Account a : accounts.values()) {
            BigDecimal sum = BigDecimal.ZERO.setScale(2, RM);
            for (Txn t : txns) {
                if (t.valid && a.accountId.equals(t.accountId)) {
                    sum = sum.add(t.adjusted).setScale(2, RM);
                }
            }
            a.eodBalance = a.startBalance.add(sum).setScale(2, RM);

            boolean promoActive = false;
            if (a.promoDays > 0) {
                int days = daysBetween(a.openedAt, bizDate);
                promoActive = days < a.promoDays;
            }

            BigDecimal apr = a.baseApr;
            if (a.eodBalance.compareTo(a.tierThreshold) >= 0) {
                apr = apr.add(a.tierApr);
            }
            if (promoActive) {
                apr = apr.add(a.promoApr);
            }
            a.apr = apr;

            BigDecimal principal = a.eodBalance.max(BigDecimal.ZERO);
            BigDecimal dailyRate = a.apr.divide(new BigDecimal("365"), 10, RM);
            a.dailyInterestRaw = principal.multiply(dailyRate).setScale(10, RM);
        }

        File interestFile = new File(OUT_DIR, "interest.csv");
        writeInterestCsv(interestFile, bizDate, accounts);

        String reportMd5 = md5HexOfFile(interestFile);

        File exceptionsFile = new File(OUT_DIR, "exceptions.csv");
        writeExceptionsCsv(exceptionsFile, txns);

        BigDecimal totalInterestRaw = BigDecimal.ZERO.setScale(10, RM);
        for (Account a : accounts.values()) {
            totalInterestRaw = totalInterestRaw.add(a.dailyInterestRaw).setScale(10, RM);
        }
        BigDecimal totalInterest = totalInterestRaw.setScale(2, RM);

        File statsFile = new File(OUT_DIR, "stats.json");
        writeStatsJsonNoNewline(statsFile, bizDate, accounts.size(), validTxs, skippedTxs, totalInterest, reportMd5);

        writeH2Db(bizDate, accounts, txns, validTxs, skippedTxs, reportMd5);
    }

    private static void deleteIfExists(File f) {
        if (f.exists()) f.delete();
    }

    private static Date readBizDate(File f) throws Exception {
        String s = readAllTrimmed(f);
        return parseDate(s);
    }

    private static String readAllTrimmed(File f) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
        try {
            StringBuilder sb = new StringBuilder();
            String line;
            while ((line = br.readLine()) != null) sb.append(line);
            return sb.toString().trim();
        } finally {
            br.close();
        }
    }

    private static List<String[]> readCsv(File f) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(f), "UTF-8"));
        try {
            List<String[]> rows = new ArrayList<String[]>();
            String line;
            while ((line = br.readLine()) != null) {
                String[] parts = line.split(",", -1);
                for (int i = 0; i < parts.length; i++) parts[i] = parts[i].trim();
                rows.add(parts);
            }
            return rows;
        } finally {
            br.close();
        }
    }

    private static Map<String, Account> readAccounts(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        Map<String, Account> m = new HashMap<String, Account>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            Account a = new Account();
            a.accountId = r[0];
            a.openedAt = parseDate(r[1]);
