            a.baseApr = new BigDecimal(r[3]);
            a.promoApr = new BigDecimal(r[4]);
            a.promoDays = Integer.parseInt(r[5]);
            a.tierThreshold = new BigDecimal(r[6]).setScale(2, RM);
