    private static Map<String, FeeRule> readFeeRules(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        Map<String, FeeRule> m = new HashMap<String, FeeRule>();
        for (int i = 1; i < rows.size(); i++) {
            String[] r = rows.get(i);
            FeeRule fr = new FeeRule();
            fr.feePlan = r[0];
            fr.appliesTo = r[1];
            fr.flatFee = new BigDecimal(r[2]);
            fr.pctFee = new BigDecimal(r[3]);
            fr.minFee = new BigDecimal(r[4]);
            fr.maxFee = new BigDecimal(r[5]);
            m.put(fr.feePlan, fr);
        }
        return m;
    }

    private static List<String> readPivots(File f) throws Exception {
        List<String[]> rows = readCsv(f);
        List<String> pivots = new ArrayList<String>();
        for (int i = 1; i < rows.size(); i++) pivots.add(rows.get(i)[0]);
