    private static int daysBetween(Date start, Date end) {
        long ms = end.getTime() - start.getTime();
        return (int)(ms / 86400000L);
    }

    private static BigDecimal computeFee(FeeRule fr, BigDecimal amountAcct) {
        if (fr == null) return BigDecimal.ZERO.setScale(2, RM);

        int sign = amountAcct.signum();
        boolean debit = sign < 0;
        boolean credit = sign > 0;

        boolean applies;
        if ("ALL".equals(fr.appliesTo)) applies = true;
        else if ("DEBIT".equals(fr.appliesTo) && debit) applies = true;
        else if ("CREDIT".equals(fr.appliesTo) && credit) applies = true;
        else applies = false;

        if (!applies) return BigDecimal.ZERO.setScale(2, RM);

        BigDecimal base = fr.flatFee.add(fr.pctFee.multiply(amountAcct.abs()));
        BigDecimal fee = base.setScale(2, RM);
        if (fee.compareTo(fr.minFee) < 0) fee = fr.minFee;
        if (fee.compareTo(fr.maxFee) > 0) fee = fr.maxFee;
        return fee.setScale(2, RM);
    }

    private static BigDecimal resolveFxRate(List<FxRate> allRates, List<String> pivots, String from, String to, Date effectiveDate) {
        BigDecimal direct = resolveFxLeg(allRates, from, to, effectiveDate);
        if (direct != null) return direct;

        for (int i = 0; i < pivots.size(); i++) {
            String p = pivots.get(i);
            if (p.equals(from) || p.equals(to)) continue;
            BigDecimal leg1 = resolveFxLeg(allRates, from, p, effectiveDate);
            if (leg1 == null) continue;
            BigDecimal leg2 = resolveFxLeg(allRates, p, to, effectiveDate);
            if (leg2 == null) continue;
            return leg1.multiply(leg2).setScale(10, RM);
        }
        return null;
    }

    private static BigDecimal resolveFxLeg(List<FxRate> allRates, String from, String to, Date effectiveDate) {
        FxRate bestDirect = latestRate(allRates, from, to, effectiveDate);
        FxRate bestReverse = latestRate(allRates, to, from, effectiveDate);

        if (bestDirect == null && bestReverse == null) return null;
        if (bestDirect != null && bestReverse == null) return bestDirect.rate.setScale(10, RM);
        if (bestDirect == null && bestReverse != null) return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);

        int cmp = bestDirect.rateDate.compareTo(bestReverse.rateDate);
        if (cmp > 0) return bestDirect.rate.setScale(10, RM);
        if (cmp < 0) return BigDecimal.ONE.divide(bestReverse.rate, 10, RM);
        return bestDirect.rate.setScale(10, RM);
    }

    private static FxRate latestRate(List<FxRate> allRates, String from, String to, Date effectiveDate) {
        FxRate best = null;
        for (int i = 0; i < allRates.size(); i++) {
            FxRate r = allRates.get(i);
            if (!r.from.equals(from)) continue;
            if (!r.to.equals(to)) continue;
            if (r.rateDate.after(effectiveDate)) continue;
            if (best == null || r.rateDate.after(best.rateDate)) best = r;
        }
        return best;
    }

    private static void writeInterestCsv(File f, Date bizDate, Map<String, Account> accounts) throws Exception {
        List<String> ids = new ArrayList<String>(accounts.keySet());
        Collections.sort(ids);

        Writer w = new OutputStreamWriter(new FileOutputStream(f), "UTF-8");
        try {
            w.write("account_id,biz_date,eod_balance,apr,daily_interest\n");
            for (int i = 0; i < ids.size(); i++) {
                Account a = accounts.get(ids.get(i));
                BigDecimal apr6 = a.apr.setScale(6, RM);
                BigDecimal di2 = a.dailyInterestRaw.setScale(2, RM);
                w.write(a.accountId);
                w.write(',');
                w.write(formatDate(bizDate));
                w.write(',');
                w.write(a.eodBalance.setScale(2, RM).toPlainString());
                w.write(',');
                w.write(apr6.toPlainString());
                w.write(',');
                w.write(di2.toPlainString());
                w.write("\n");
            }
        } finally {
            w.close();
        }
    }

    private static void writeExceptionsCsv(File f, List<Txn> txns) throws Exception {
        Writer w = new OutputStreamWriter(new FileOutputStream(f), "UTF-8");
        try {
            w.write("row_num,tx_id,reason\n");
            for (int i = 0; i < txns.size(); i++) {
                Txn t = txns.get(i);
                if (t.valid) continue;
                w.write(Integer.toString(t.rowNum));
                w.write(',');
                w.write(t.txId);
                w.write(',');
                w.write(t.reason);
                w.write("\n");
            }
        } finally {
            w.close();
        }
    }

    private static String md5HexOfFile(File f) throws Exception {
        MessageDigest md = MessageDigest.getInstance("MD5");
        InputStream is = new FileInputStream(f);
        try {
            byte[] buf = new byte[8192];
            int n;
            while ((n = is.read(buf)) > 0) md.update(buf, 0, n);
        } finally {
            is.close();
        }
        byte[] dig = md.digest();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < dig.length; i++) {
            int b = dig[i] & 0xFF;
            String hx = Integer.toHexString(b);
            if (hx.length() == 1) sb.append('0');
            sb.append(hx);
        }
        return sb.toString();
    }

    private static void writeStatsJsonNoNewline(File f, Date bizDate, int accounts, int validTxs, int skippedTxs,
                                               BigDecimal totalInterest, String reportMd5) throws Exception {
        // single line, no trailing newline
        StringBuilder sb = new StringBuilder();
        sb.append('{');
        sb.append("\"business_date\":\"").append(formatDate(bizDate)).append("\"");
        sb.append(",\"accounts\":").append(accounts);
        sb.append(",\"valid_txs\":").append(validTxs);
        sb.append(",\"skipped_txs\":").append(skippedTxs);
        sb.append(",\"total_interest\":").append(totalInterest.setScale(2, RM).toPlainString());
        sb.append(",\"report_md5\":\"").append(reportMd5).append("\"");
        sb.append('}');

        OutputStream os = new FileOutputStream(f);
        try {
            os.write(sb.toString().getBytes("UTF-8"));
        } finally {
            os.close();
        }
    }

