      "keystrokes": "cat >> /app/src/BankBatchJob.java <<'EOF'\n  private static BigDecimal fee(Fee fr, BigDecimal amtCcy) {\n    if (fr==null) return bd(\"0\").setScale(2,RM);\n    int s = amtCcy.signum(); boolean debit=s<0, credit=s>0;\n    boolean applies = \"ALL\".equals(fr.applies) || (\"DEBIT\".equals(fr.applies)&&debit) || (\"CREDIT\".equals(fr.applies)&&credit);\n    if (!applies) return bd(\"0\").setScale(2,RM);\n    BigDecimal base = fr.flat.add(fr.pct.multiply(amtCcy.abs()));\n    BigDecimal f = base.setScale(2,RM);\n    if (f.compareTo(fr.min)<0) f=fr.min;\n    if (f.compareTo(fr.max)>0) f=fr.max;\n    return f.setScale(2,RM);\n  }\n\n  private static Fx latest(List<Fx> all, String from, String to, Date eff) {\n    Fx best=null;\n    for (Fx r: all) {\n      if (!r.f.equals(from) || !r.t.equals(to)) continue;\n      if (r.d.after(eff)) continue;\n      if (best==null || r.d.after(best.d)) best=r;\n    }\n    return best;\n  }\n\n  private static BigDecimal leg(List<Fx> all, String from, String to, Date eff) {\n    Fx d = latest(all, from, to, eff);\n    Fx rev = latest(all, to, from, eff);\n    if (d==null && rev==null) return null;\n    if (d!=null && rev==null) return d.r.setScale(10,RM);\n    if (d==null && rev!=null) return bd(\"1\").divide(rev.r,10,RM);\n    int cmp = d.d.compareTo(rev.d);\n    if (cmp>0) return d.r.setScale(10,RM);\n    if (cmp<0) return bd(\"1\").divide(rev.r,10,RM);\n    return d.r.setScale(10,RM);\n  }\n\n  private static BigDecimal fxRate(List<Fx> all, List<String> pivots, String from, String to, Date eff) {\n    BigDecimal x = leg(all,from,to,eff);\n    if (x!=null) return x;\n    for (String p: pivots) {\n      if (p.equals(from) || p.equals(to)) continue;\n      BigDecimal a = leg(all,from,p,eff); if (a==null) continue;\n      BigDecimal b = leg(all,p,to,eff); if (b==null) continue;\n      return a.multiply(b).setScale(10,RM);\n    }\n    return null;\n  }\n\n  private static void writeInterest(File f, Date biz, Map<String,Acct> accts) throws Exception {\n    List<String> ids=new ArrayList<String>(accts.keySet()); Collections.sort(ids);\n    Writer w=new OutputStreamWriter(new FileOutputStream(f),\"UTF-8\");\n    try{\n      w.write(\"account_id,biz_date,eod_balance,apr,daily_interest\\n\");\n      for(String id: ids){\n        Acct a=accts.get(id);\n        w.write(a.id+\",\"+fmt(biz)+\",\"+a.eod.setScale(2,RM).toPlainString()+\",\"+a.apr.setScale(6,RM).toPlainString()+\",\"+a.diRaw.setScale(2,RM).toPlainString()+\"\\n\");\n      }\n    } finally { w.close(); }\n  }\n\n  private static void writeExceptions(File f, List<Txn> txns) throws Exception {\n    Writer w=new OutputStreamWriter(new FileOutputStream(f),\"UTF-8\");\n    try{\n      w.write(\"row_num,tx_id,reason\\n\");\n      for(Txn t: txns) if(!t.valid) w.write(t.row+\",\"+t.txId+\",\"+t.reason+\"\\n\");\n    } finally { w.close(); }\n  }\n\n  private static String md5hex(File f) throws Exception {\n    MessageDigest md=MessageDigest.getInstance(\"MD5\");\n    InputStream is=new FileInputStream(f);\n    try{ byte[] buf=new byte[8192]; int n; while((n=is.read(buf))>0) md.update(buf,0,n); }\n    finally{ is.close(); }\n    byte[] d=md.digest();\n    StringBuilder sb=new StringBuilder();\n    for(int i=0;i<d.length;i++){ int b=d[i]&0xFF; String h=Integer.toHexString(b); if(h.length()==1) sb.append('0'); sb.append(h); }\n    return sb.toString();\n  }\n\n  private static void writeStats(File f, Date biz, int accounts, int valid, int skipped, BigDecimal total, String md5) throws Exception {\n    String s = \"{\\\"business_date\\\":\\\"\"+fmt(biz)+\"\\\",\\\"accounts\\\":\"+accounts+\",\\\"valid_txs\\\":\"+valid+\",\\\"skipped_txs\\\":\"+skipped+\",\\\"total_interest\\\":\"+total.setScale(2,RM).toPlainString()+\",\\\"report_md5\\\":\\\"\"+md5+\"\\\"}\";\n    OutputStream os=new FileOutputStream(f);\n    try{ os.write(s.getBytes(\"UTF-8\")); } finally { os.close(); }\n  }\n\n  private static void safe(Statement st, String sql){ try{ st.execute(sql);}catch(SQLException e){} }\n\n  private static void writeDb(Date biz, Map<String,Acct> accts, List<Txn> txns, int valid, int skipped, String md5) throws Exception {\n    Class.forName(\"org.h2.Driver\");\n    Connection c=DriverManager.getConnection(JDBC_URL,\"sa\",\"\");\n    try{\n      c.setAutoCommit(false);\n      Statement st=c.createStatement();\n      try{\n        safe(st,\"DROP TABLE RUN_AUDIT\"); safe(st,\"DROP TABLE TXNS\"); safe(st,\"DROP TABLE ACCOUNTS\");\n        st.execute(\"CREATE TABLE ACCOUNTS (ACCOUNT_ID VARCHAR(20) PRIMARY KEY, OPENED_AT VARCHAR(10), START_BALANCE DECIMAL(18,2), BASE_APR DECIMAL(18,8), PROMO_APR DECIMAL(18,8), PROMO_DAYS INTEGER, TIER_THRESHOLD DECIMAL(18,2), TIER_APR DECIMAL(18,8), CURRENCY VARCHAR(3), FEE_PLAN VARCHAR(20))\");\n        st.execute(\"CREATE TABLE TXNS (ROW_NUM INTEGER PRIMARY KEY, TX_ID VARCHAR(40), ACCOUNT_ID VARCHAR(20), EFFECTIVE_DATE VARCHAR(10), AMOUNT DECIMAL(18,2), CURRENCY VARCHAR(3), STATUS VARCHAR(20), REVERSAL_OF VARCHAR(40))\");\n        st.execute(\"CREATE TABLE RUN_AUDIT (JDBC_URL VARCHAR(200), BIZ_DATE VARCHAR(10), ACCOUNTS INTEGER, VALID_TXS INTEGER, SKIPPED_TXS INTEGER, REPORT_MD5 VARCHAR(40))\");\n      } finally { st.close(); }\n\n      PreparedStatement pa=c.prepareStatement(\"INSERT INTO ACCOUNTS(ACCOUNT_ID,OPENED_AT,START_BALANCE,BASE_APR,PROMO_APR,PROMO_DAYS,TIER_THRESHOLD,TIER_APR,CURRENCY,FEE_PLAN) VALUES (?,?,?,?,?,?,?,?,?,?)\");\n      try{\n        List<String> ids=new ArrayList<String>(accts.keySet()); Collections.sort(ids);\n        for(String id: ids){\n          Acct a=accts.get(id);\n          pa.setString(1,a.id); pa.setString(2,fmt(a.opened)); pa.setBigDecimal(3,a.start.setScale(2,RM));\n          pa.setBigDecimal(4,a.baseApr); pa.setBigDecimal(5,a.promoApr); pa.setInt(6,a.promoDays);\n          pa.setBigDecimal(7,a.tierTh.setScale(2,RM)); pa.setBigDecimal(8,a.tierApr);\n          pa.setString(9,a.ccy); pa.setString(10,a.feePlan);\n          pa.executeUpdate();\n        }\n      } finally { pa.close(); }\n\n      PreparedStatement pt=c.prepareStatement(\"INSERT INTO TXNS(ROW_NUM,TX_ID,ACCOUNT_ID,EFFECTIVE_DATE,AMOUNT,CURRENCY,STATUS,REVERSAL_OF) VALUES (?,?,?,?,?,?,?,?)\");\n      try{\n        for(Txn t: txns){\n          pt.setInt(1,t.row); pt.setString(2,t.txId); pt.setString(3,t.acctId); pt.setString(4,fmt(t.eff));\n          pt.setBigDecimal(5,t.amt.setScale(2,RM)); pt.setString(6,t.ccy); pt.setString(7,t.status);\n          pt.setString(8,t.revOf==null?\"\":t.revOf);\n          pt.executeUpdate();\n        }\n      } finally { pt.close(); }\n\n      PreparedStatement pr=c.prepareStatement(\"INSERT INTO RUN_AUDIT(JDBC_URL,BIZ_DATE,ACCOUNTS,VALID_TXS,SKIPPED_TXS,REPORT_MD5) VALUES (?,?,?,?,?,?)\");\n      try{\n        pr.setString(1,JDBC_URL); pr.setString(2,fmt(biz)); pr.setInt(3,accts.size());\n        pr.setInt(4,valid); pr.setInt(5,skipped); pr.setString(6,md5);\n        pr.executeUpdate();\n      } finally { pr.close(); }\n\n      c.commit();\n    } finally { try{ c.close(); }catch(Exception e){} }\n  }\n}\nEOF\n",
